bg=3
motifs={8:['100','110','001'],6:['001','110','001'],9:['101','010','111'],4:['111','010','110'],7:['010','101','111'],1:['011','010','011']}
# output tile: background border, inverse mini-mask inside
layouts=[[(8,6),(9,4),(7,1)]]
out=[[bg]*13 for _ in range(19)]
for band, pair in enumerate(layouts[0]):
 top=1+6*band
 for j,color in enumerate(pair):
  left=1+6*j
  for rr in range(5):
   for cc in range(5): out[top+rr][left+cc]=color
  for rr in range(3):
   for cc in range(3):
    if motifs[color][rr][cc]=='1': out[top+1+rr][left+1+cc]=bg
print('\n'.join(' '.join(map(str,r)) for r in out))
